#!/bin/bash
set -euo pipefail
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B - <<'ZJ_FAIR_DEPLOY'
"""Deploy only the sealed fair-comparison source into one new cluster root."""
from __future__ import annotations

import base64
from io import BytesIO
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import stat
import tarfile


PAYLOAD = ""
RECEIPT = ""


def sha(data):
    return hashlib.sha256(data).hexdigest()


def canonical(value):
    return json.dumps(value, sort_keys=True, ensure_ascii=False,
                      separators=(",", ":"), allow_nan=False).encode()


def write_new(path, raw):
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
    handle = os.open(path, flags, 0o600)
    with os.fdopen(handle, "wb") as stream:
        stream.write(raw)
        stream.flush()
        os.fsync(stream.fileno())


def copy_checked(src, dst, spec):
    if (src.is_symlink() or not src.is_file() or src.stat().st_size != spec["size_bytes"]
            or not str(src).startswith("/data1/home/sunyiq/")):
        raise ValueError("registered source input missing or changed: " + str(src))
    dst.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(dst, flags, 0o600)
    digest = hashlib.sha256()
    count = 0
    with src.open("rb") as source, os.fdopen(fd, "wb") as target:
        for block in iter(lambda: source.read(1 << 20), b""):
            digest.update(block)
            target.write(block)
            count += len(block)
        target.flush()
        os.fsync(target.fileno())
    if count != spec["size_bytes"] or digest.hexdigest() != spec["sha256"]:
        raise ValueError("registered source input hash differs: " + str(src))


def main():
    os.umask(0o077)
    receipt = json.loads(base64.b64decode(RECEIPT, validate=True))
    raw = base64.b64decode(PAYLOAD, validate=True)
    if (len(raw) != receipt["payload_bytes"] or sha(raw) != receipt["payload_sha256"]
            or len(raw) > 1_000_000):
        raise ValueError("deployment payload identity differs")
    root = Path(receipt["remote_root"])
    if (str(root) != "/data1/home/sunyiq/zhenjiang_fair_comparison_20260928_002"
            or root.parent.resolve(strict=True) != root.parent or os.path.lexists(root)):
        raise ValueError("exclusive cluster root already exists or parent differs")
    members = {}
    with tarfile.open(fileobj=BytesIO(raw), mode="r:gz") as archive:
        for item in archive.getmembers():
            name = item.name
            parsed = PurePosixPath(name)
            if (not item.isfile() or parsed.is_absolute() or ".." in parsed.parts
                    or "\\" in name or name in members or item.size > 1_000_000):
                raise ValueError("unsafe payload member")
            content = archive.extractfile(item)
            if content is None:
                raise ValueError("unreadable payload member")
            data = content.read(item.size + 1)
            if len(data) != item.size:
                raise ValueError("payload member size differs")
            members[name] = data
    index_raw = members.get("deploy/payload_index.json")
    if index_raw is None or sha(index_raw) != receipt["payload_index_sha256"]:
        raise ValueError("deployment payload index differs")
    index = json.loads(index_raw)
    if (set(index) != set(members) - {"deploy/payload_index.json"}
            or len(members) != receipt["members"]):
        raise ValueError("deployment payload member count differs")
    for name, spec in index.items():
        if len(members[name]) != spec["bytes"] or sha(members[name]) != spec["sha256"]:
            raise ValueError("deployment payload member hash differs: " + name)
    protocol = json.loads(members["protocol.json"])
    manifest_raw = members["reports/training_manifest.json"]
    manifest = json.loads(manifest_raw)
    if (sha(members["protocol.json"]) != receipt["remote_protocol_sha256"]
            or sha(manifest_raw) != receipt["remote_manifest_sha256"]
            or sha(members["deploy/job.sh"]) != receipt["job_sha256"]
            or protocol["remote_root"] != str(root)
            or protocol["local_root"] != str(root)
            or protocol["local_protocol_sha256"] != receipt["local_protocol_sha256"]
            or len(protocol["training_inputs"]) != receipt["source_data_files"]
            or manifest["file_count"] != len(manifest["files"])):
        raise ValueError("remote protocol or training manifest differs")
    for name, spec in manifest["files"].items():
        if name in members and (len(members[name]) != spec["bytes"]
                                or sha(members[name]) != spec["sha256"]):
            raise ValueError("sealed science source differs: " + name)
    # All payload and path checks finish before the root is created.
    root.mkdir(mode=0o700)
    for name, data in sorted(members.items()):
        write_new(root.joinpath(*PurePosixPath(name).parts), data)
    for spec in protocol["training_inputs"]:
        relative = PurePosixPath(spec["relative_path"])
        if relative.is_absolute() or ".." in relative.parts:
            raise ValueError("source input escapes deployment root")
        copy_checked(Path(spec["path"]), root.joinpath(*relative.parts), spec)
    for name, spec in manifest["files"].items():
        path = root.joinpath(*PurePosixPath(name).parts)
        if path.is_symlink() or not path.is_file() or path.stat().st_size != spec["bytes"]:
            raise ValueError("deployed science file differs: " + name)
        with path.open("rb") as stream:
            digest = hashlib.sha256()
            for block in iter(lambda: stream.read(1 << 20), b""):
                digest.update(block)
        if digest.hexdigest() != spec["sha256"]:
            raise ValueError("deployed science file hash differs: " + name)
    (root / "slurm").mkdir(mode=0o700)
    meta = root.stat()
    binding = {"device": meta.st_dev, "inode": meta.st_ino,
               "uid": meta.st_uid, "mode": stat.S_IMODE(meta.st_mode)}
    if binding["mode"] != 0o700:
        raise ValueError("private cluster root mode differs")
    deployment = {"status": "DEPLOYED_NO_TRAINING", "root": str(root),
                  "root_binding": binding,
                  "payload_sha256": receipt["payload_sha256"],
                  "protocol_sha256": receipt["remote_protocol_sha256"],
                  "manifest_sha256": receipt["remote_manifest_sha256"],
                  "job_sha256": receipt["job_sha256"],
                  "source_data_files": len(protocol["training_inputs"])}
    deployed_raw = canonical(deployment)
    write_new(root / "deploy/deployment.json", deployed_raw)
    print(json.dumps({**deployment, "deployment_sha256": sha(deployed_raw)}, sort_keys=True))


if __name__ == "__main__":
    main()

ZJ_FAIR_DEPLOY
